# csv_aggregator.py
"""Stream a large CSV, validate columns, normalize timestamps to UTC,
and aggregate totals by account without loading all rows into memory."""

from __future__ import annotations

import csv
import logging
from dataclasses import dataclass, field
from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation
from io import TextIOBase
from typing import (
    Callable,
    Dict,
    Iterable,
    Iterator,
    List,
    Mapping,
    Optional,
    Sequence,
    Tuple,
    Union,
)

logger = logging.getLogger(__name__)

TimestampParser = Callable[[str], datetime]


class CSVValidationError(Exception):
    """Raised when the CSV structure is invalid (e.g., missing columns)."""


class RowError(Exception):
    """Raised for a single bad row; processing may continue."""


@dataclass(frozen=True)
class CSVSchema:
    """Declares the columns the aggregator expects."""

    account_column: str
    amount_column: str
    timestamp_column: str
    required_columns: Tuple[str, ...] = ()

    def all_required(self) -> Tuple[str, ...]:
        base = {self.account_column, self.amount_column, self.timestamp_column}
        return tuple(base.union(self.required_columns))


@dataclass
class RowResult:
    """Parsed, normalized representation of one CSV row."""

    account: str
    amount: Decimal
    timestamp_utc: datetime
    raw: Mapping[str, str] = field(repr=False)


@dataclass
class AggregationResult:
    """Final output of a streaming aggregation run."""

    totals: Dict[str, Decimal]
    row_count: int
    error_count: int
    errors: List[str] = field(default_factory=list)

    @property
    def grand_total(self) -> Decimal:
        return sum(self.totals.values(), Decimal("0"))


def default_timestamp_parser(value: str, default_tz: timezone = timezone.utc) -> datetime:
    """Parse an ISO-8601 timestamp; naive values are assumed to be in `default_tz`.
    Always returns an aware datetime in UTC."""
    text = value.strip()
    if not text:
        raise RowError("empty timestamp")
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError as exc:
        raise RowError(f"unparseable timestamp {value!r}") from exc
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=default_tz)
    return parsed.astimezone(timezone.utc)


def make_timestamp_parser(default_tz: timezone = timezone.utc) -> TimestampParser:
    """Factory for a parser bound to a default timezone for naive timestamps."""
    return lambda value: default_timestamp_parser(value, default_tz)


def _validate_header(reader: csv.DictReader, schema: CSVSchema) -> None:
    header = reader.fieldnames
    if not header:
        raise CSVValidationError("CSV file has no header row")
    missing = [col for col in schema.all_required() if col not in header]
    if missing:
        raise CSVValidationError(f"missing required columns: {missing}")


def iter_rows(
    source: TextIOBase,
    schema: CSVSchema,
    timestamp_parser: Optional[TimestampParser] = None,
    max_errors: Optional[int] = None,
) -> Iterator[Union[RowResult, RowError]]:
    """Lazily yield RowResult for valid rows and RowError for bad ones.

    Stops early if `max_errors` bad rows is exceeded (raises CSVValidationError).
    """
    parse_ts = timestamp_parser or default_timestamp_parser
    reader = csv.DictReader(source)
    _validate_header(reader, schema)

    errors = 0
    for line_no, raw in enumerate(reader, start=2):  # header is line 1
        try:
            account = (raw.get(schema.account_column) or "").strip()
            if not account:
                raise RowError(f"line {line_no}: empty account")

            amount_text = (raw.get(schema.amount_column) or "").strip()
            try:
                amount = Decimal(amount_text)
            except InvalidOperation as exc:
                raise RowError(
                    f"line {line_no}: invalid amount {amount_text!r}"
                ) from exc

            ts_text = raw.get(schema.timestamp_column) or ""
            try:
                ts_utc = parse_ts(ts_text)
            except RowError as exc:
                raise RowError(f"line {line_no}: {exc}") from exc

            yield RowResult(account=account, amount=amount, timestamp_utc=ts_utc, raw=raw)

        except RowError as row_exc:
            errors += 1
            logger.warning("%s", row_exc)
            if max_errors is not None and errors > max_errors:
                raise CSVValidationError(
                    f"exceeded max_errors={max_errors}"
                ) from row_exc
            yield row_exc


def aggregate_by_account(
    source: TextIOBase,
    schema: CSVSchema,
    timestamp_parser: Optional[TimestampParser] = None,
    max_errors: Optional[int] = None,
) -> AggregationResult:
    """Stream `source` and sum amounts per account. Memory usage is bounded
    by the number of distinct accounts, not the number of rows."""
    totals: Dict[str, Decimal] = {}
    row_count = 0
    error_count = 0
    error_samples: List[str] = []

    for item in iter_rows(source, schema, timestamp_parser, max_errors):
        if isinstance(item, RowError):
            error_count += 1
            if len(error_samples) < 100:
                error_samples.append(str(item))
        else:
            row_count += 1
            totals[item.account] = totals.get(item.account, Decimal("0")) + item.amount

    return AggregationResult(
        totals=totals,
        row_count=row_count,
        error_count=error_count,
        errors=error_samples,
    )


def aggregate_files(
    sources: Iterable[TextIOBase],
    schema: CSVSchema,
    **kwargs: object,
) -> AggregationResult:
    """Aggregate multiple CSV streams into a single result."""
    combined: Dict[str, Decimal] = {}
    total_rows = 0
    total_errors = 0
    all_error_samples: List[str] = []

    for source in sources:
        result = aggregate_by_account(source, schema, **kwargs)  # type: ignore[arg-type]
        for account, amount in result.totals
